// Keep the selection, including every deck card type, within the visible viewport.
function explorerFitScale(width,height,availableWidth,availableHeight){return Math.min(1,Math.max(1,availableWidth)/Math.max(1,width),Math.max(1,availableHeight)/Math.max(1,height));}
// Choose the largest uniform card scale that keeps every type visible.
const EXPLORER_CARD_METRICS={width:219.12,minHeight:323.4,gap:7.92};
function explorerCardGrid(count,width,height,cardHeight=EXPLORER_CARD_METRICS.minHeight){if(!count)return {columns:1,scale:1};let best={columns:1,scale:0};for(let columns=1;columns<=count;columns++){const rows=Math.ceil(count/columns),scale=Math.max(.01,Math.min(1,(width-(columns-1)*EXPLORER_CARD_METRICS.gap)/(columns*EXPLORER_CARD_METRICS.width),(height-(rows-1)*EXPLORER_CARD_METRICS.gap)/(rows*cardHeight)));if(scale>best.scale)best={columns,scale};}return best;}
function layoutExplorerDeck(viewportHeight,root=document){const deck=root.querySelector('.explorer-deck-cards');if(!deck?.querySelectorAll||!deck.clientWidth)return;const slots=[...deck.querySelectorAll('.explorer-card-slot')];if(!slots.length)return;const cardHeight=EXPLORER_CARD_METRICS.minHeight,grid=explorerCardGrid(6,deck.clientWidth,Math.max(132,Math.min(369.6,viewportHeight*.396)),cardHeight);deck.style.setProperty('--deck-columns',6);deck.style.setProperty('--deck-card-scale',grid.scale);}

let explorerFitFrame=0,explorerWasVisible=false,explorerMeasuring=false;
function fitExplorerSelection(){if(globalThis.ASHBOUND_HEADLESS||explorerMeasuring)return;const el=document.querySelector('.explorer-selection');if(!el?.cloneNode||!el.offsetWidth||!el.parentElement)return;const parent=el.parentElement,viewport=window.visualViewport,viewportHeight=viewport?.height||window.innerHeight,viewportWidth=viewport?.width||window.innerWidth,top=el.getBoundingClientRect().top,computed=typeof getComputedStyle==='function'?getComputedStyle(parent):null,width=Math.max(1,parent.clientWidth-(parseFloat(computed?.paddingLeft)||0)-(parseFloat(computed?.paddingRight)||0)),measure=el.cloneNode(true);explorerMeasuring=true;
try{measure.classList.add('explorer-measure');measure.setAttribute('aria-hidden','true');measure.inert=true;Object.assign(measure.style,{position:'fixed',left:'-100000px',top:'0',width:width+'px',zoom:'1',visibility:'hidden',pointerEvents:'none',contain:'layout style paint'});parent.append(measure);layoutExplorerDeck(viewportHeight,measure);const rect=measure.getBoundingClientRect(),scale=explorerFitScale(rect.width,rect.height,viewportWidth-16,viewportHeight-Math.max(0,top)-76),deck=el.querySelector('.explorer-deck-cards'),measuredDeck=measure.querySelector('.explorer-deck-cards');if(deck&&measuredDeck)for(const property of ['--deck-columns','--deck-card-scale']){const value=measuredDeck.style.getPropertyValue(property);if(deck.style.getPropertyValue(property)!==value)deck.style.setProperty(property,value);}const fittedWidth=measure.offsetWidth+'px',fittedZoom=String(scale);if(el.style.width!==fittedWidth)el.style.width=fittedWidth;if(el.style.zoom!==fittedZoom)el.style.zoom=fittedZoom;el.dataset.fitted='true';}finally{measure.remove();explorerMeasuring=false;}}
function scheduleExplorerFit(){if(globalThis.ASHBOUND_HEADLESS||!document.documentElement?.style?.setProperty||explorerFitFrame)return;explorerFitFrame=requestAnimationFrame(()=>{explorerFitFrame=0;fitExplorerSelection();});}
const explorerFitRenderBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;explorerFitRenderBase();const visible=page==='characters'&&!S.run;if(visible){if(!explorerWasVisible)window.scrollTo?.(0,0);fitExplorerSelection();}explorerWasVisible=visible;};
const explorerFitDisplayBase=applyDisplay;applyDisplay=function(){explorerFitDisplayBase();scheduleExplorerFit();};
window.addEventListener('resize',scheduleExplorerFit);window.visualViewport?.addEventListener('resize',scheduleExplorerFit);document.fonts?.ready?.then(scheduleExplorerFit);
if(!globalThis.ASHBOUND_HEADLESS)render();

